  padding: 80px 0;
  background: #f6f2ea;
  min-height: 70vh;
}

.booking-shell {
  max-width: 1120px;
  margin: 0 auto;
}

.section-head {
  margin-bottom: 28px;
  max-width: 760px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.78rem;
  color: #b58b4a;
  font-weight: 700;
}

h1 {
  color: #08263a;
  margin: 8px 0;
}

.booking-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 18px;
}

.booking-card, .booking-detail-card, .empty-card {
  background: #fff;
  border-radius: 24px;
  padding: 24px;
  box-shadow: 0 18px 45px rgba(8, 38, 58, 0.08);
  border: 1px solid rgba(8, 38, 58, 0.08);
}

.booking-card h2 {
  margin: 12px 0 8px;
  color: #08263a;
  font-size: 1.25rem;
}

.booking-card p {
  margin: 4px 0;
  color: #516070;
}

.status-pill {
  display: inline-flex;
  border-radius: 999px;
  background: rgba(181, 139, 74, 0.12);
  color: #8a652d;
  padding: 6px 10px;
  font-size: 0.78rem;
  font-weight: 700;
}

.booking-meta {
  display: grid;
  gap: 6px;
  margin: 18px 0;
  color: #08263a;
}

.booking-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  border: 0;
  border-radius: 999px;
  padding: 10px 16px;
  font-weight: 700;
  cursor: pointer;
  text-decoration: none;
}

.btn-primary {
  background: #08263a;
  color: #fff;
}

.btn-secondary {
  background: #efe7da;
  color: #08263a;
}

.muted {
  color: #667;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 14px;
  margin: 24px 0;
}

.detail-grid div {
  background: #f8f5ef;
  border-radius: 16px;
  padding: 14px;
  display: grid;
  gap: 4px;
}

.detail-grid strong {
  color: #08263a;
}

.detail-grid span {
  color: #516070;
}

.comments {
  background: #f8f5ef;
  padding: 16px;
  border-radius: 16px;
  color: #516070;
}

.payment-admin-card {
  background: #fff;
  border-radius: 24px;
  padding: 24px;
  margin: 24px 0;
  box-shadow: 0 18px 45px rgba(8, 38, 58, 0.08);
  border: 1px solid rgba(8, 38, 58, 0.08);
}

.payment-admin-card h2 {
  margin-top: 0;
  color: #08263a;
}

.payment-summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
  margin: 16px 0;
}

.payment-summary div {
  background: #f8f5ef;
  border-radius: 16px;
  padding: 14px;
  display: grid;
  gap: 4px;
}

.collect-balance {
  display: grid;
  gap: 12px;
}

.collect-balance label {
  display: grid;
  gap: 0.4rem;
  color: #08263a;
  font-weight: 700;
}

.collect-balance select,
.collect-balance textarea {
  border: 1px solid rgba(8, 38, 58, 0.16);
  border-radius: 14px;
  padding: 0.75rem;
  font: inherit;
}

.paid-badge {
  display: inline-flex;
  border-radius: 999px;
  padding: 0.55rem 0.9rem;
  background: #047857;
  color: #fff;
  font-weight: 700;
}

.success {
  color: #047857;
  font-weight: 700;
}

.error-message {
  color: #9f1d1d;
  font-weight: 700;
}

.blocked-note {
  background: rgba(181, 139, 74, 0.12);
  color: #8a652d;
  border: 1px solid rgba(181, 139, 74, 0.25);
  border-radius: 14px;
  padding: 0.85rem 1rem;
  font-weight: 700;
}

.warranty-actions {
  background: #f8f5ef;
  border: 1px solid rgba(8, 38, 58, 0.08);
  border-radius: 16px;
  padding: 1rem;
  margin: 1rem 0;
}

.warranty-actions p {
  margin-top: 0;
  color: #516070;
}

.cash-damage-card {
  background: #fff7ed;
  border: 1px solid rgba(242, 140, 40, 0.25);
  border-radius: 16px;
  padding: 1rem;
  margin: 1rem 0;
}

.cash-damage-card h3 {
  margin-top: 0;
  color: #08263a;
}

.cash-damage-card label {
  display: grid;
  gap: 0.4rem;
  margin: 0.85rem 0;
  color: #08263a;
  font-weight: 700;
}

.cash-damage-card input,
.cash-damage-card textarea {
  border: 1px solid rgba(8, 38, 58, 0.16);
  border-radius: 14px;
  padding: 0.75rem;
  font: inherit;
  background: #fff;
